// src/pages/CreerCours.jsx - Version clean
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './CreerCours.css';

const CreerCours = () => {
  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    matiere: '',
    niveau: 'débutant',
    estPublic: true,
    fichierCours: null
  });
  const [isLoading, setIsLoading] = useState(false);
  const [filePreview, setFilePreview] = useState(null);
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    
    if (type === 'file') {
      const file = files[0];
      setFormData(prev => ({ ...prev, fichierCours: file }));
      
      if (file) {
        setFilePreview({
          name: file.name,
          size: (file.size / (1024 * 1024)).toFixed(2),
          type: file.type
        });
      } else {
        setFilePreview(null);
      }
    } else if (type === 'checkbox') {
      setFormData(prev => ({ ...prev, [name]: checked }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const token = localStorage.getItem('token');
    if (!token) {
      alert('Vous devez être connecté');
      navigate('/login');
      return;
    }

    try {
      const submitData = {
        titre: formData.titre,
        description: formData.description,
        matiere: formData.matiere,
        niveau: formData.niveau,
        estPublic: formData.estPublic
      };

      console.log('📤 Création cours:', submitData);

      const res = await axios.post('http://localhost:5000/api/courses', submitData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      console.log('✅ Cours créé:', res.data);
      alert('Cours créé avec succès !');
      navigate('/dashboard-prof');

    } catch (err) {
      console.error('❌ Erreur:', err);
      alert(err.response?.data?.message || 'Erreur création cours');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    navigate('/dashboard-prof');
  };

  const getFileIcon = (fileType) => {
    if (fileType?.includes('pdf')) return '📕';
    if (fileType?.includes('word')) return '📄';
    if (fileType?.includes('powerpoint')) return '📊';
    if (fileType?.includes('zip')) return '📦';
    return '📁';
  };

  return (
    <div className="creer-cours-container">
      <div className="creer-cours-card">
        <div className="creer-cours-header">
          <button className="back-btn" onClick={handleCancel}>← Retour</button>
          <h1>Créer un nouveau cours</h1>
          <p>Remplissez les informations pour créer votre cours</p>
        </div>

        <form onSubmit={handleSubmit} className="creer-cours-form">
          <div className="form-group">
            <label>Titre du cours *</label>
            <input
              type="text"
              name="titre"
              value={formData.titre}
              onChange={handleInputChange}
              placeholder="Ex: Mathématiques Avancées"
              required
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label>Description *</label>
            <textarea
              name="description"
              value={formData.description}
              onChange={handleInputChange}
              placeholder="Description du cours..."
              required
              rows="4"
              className="form-textarea"
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Matière *</label>
              <select
                name="matiere"
                value={formData.matiere}
                onChange={handleInputChange}
                required
                className="form-select"
              >
                <option value="">Sélectionnez une matière</option>
                <option value="mathématiques">Mathématiques</option>
                <option value="physique">Physique</option>
                <option value="informatique">Informatique</option>
                <option value="autres">Autres</option>
              </select>
            </div>

            <div className="form-group">
              <label>Niveau *</label>
              <select
                name="niveau"
                value={formData.niveau}
                onChange={handleInputChange}
                required
                className="form-select"
              >
                <option value="débutant">Débutant</option>
                <option value="intermédiaire">Intermédiaire</option>
                <option value="avancé">Avancé</option>
              </select>
            </div>
          </div>

          <div className="form-group">
            <label>
              <input
                type="checkbox"
                name="estPublic"
                checked={formData.estPublic}
                onChange={handleInputChange}
              />
              Cours public
            </label>
          </div>

          <div className="form-actions">
            <button type="button" className="cancel-btn" onClick={handleCancel}>
              Annuler
            </button>
            <button type="submit" className="submit-btn" disabled={isLoading}>
              {isLoading ? 'Création...' : 'Créer le cours'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

// EXPORT TRÈS IMPORTANT !
export default CreerCours;
